from collections import deque

grid = [
    [8, 5, 8, 5, 8, 5, 5, 5, 8, 8, 5, 5, 5, 8, 5, 8, 5],
    [5, 5, 5, 5, 5, 8, 5, 8, 8, 8, 5, 5, 8, 8, 8, 8, 5],
    [5, 5, 8, 5, 5, 5, 5, 5, 8, 8, 5, 5, 8, 8, 8, 8, 5],
    [8, 5, 5, 8, 5, 8, 8, 5, 8, 8, 5, 5, 5, 8, 5, 8, 8],
    [5, 5, 5, 5, 5, 5, 8, 5, 8, 8, 8, 5, 5, 8, 5, 8, 5],
    [8, 8, 5, 5, 8, 5, 5, 5, 8, 8, 5, 5, 5, 8, 5, 8, 5],
    [5, 5, 5, 8, 8, 5, 5, 5, 8, 8, 8, 5, 5, 8, 5, 8, 5],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8],
    [5, 5, 5, 5, 8, 8, 5, 5, 8, 8, 5, 8, 5, 8, 5, 8, 5]
]

h, w = len(grid), len(grid[0])

# Find all 8s
eights = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]

# BFS to find connected components
def get_neighbors(r, c):
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8:
            yield (nr, nc)

visited = set()
components = []

for start in eights:
    if start in visited:
        continue
    component = []
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))
        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                queue.append((nr, nc))
    components.append(component)

print(f"Found {len(components)} connected components")
for i, comp in enumerate(components):
    print(f"  Component {i}: size={len(comp)}, cells={sorted(comp)[:5]}...")

# Create component lookup
comp_lookup = {}
for comp in components:
    for cell in comp:
        comp_lookup[cell] = comp

# Map small components to indices
small_components = []
large_component = None
for i, comp in enumerate(components):
    if len(comp) == 1:
        small_components.append(i)
    elif len(comp) >= 2:
        large_component = i

print(f"\nSmall components: {small_components}")
print(f"Large component: {large_component}")

